export type Kind = 'build'|'weapon'|'ash'|'talisman'|'spell'|'boss'|'guide';
export type Stat = 'VIG'|'MND'|'END'|'STR'|'DEX'|'INT'|'FTH'|'ARC';
export type Stats = Record<Stat,number>;
export type Section = {title:string; paragraphs:string[]};
export type Source = {label:string;url:string};
export type Loadout = {id:string; role:string;note:string};
export type Build = {className:keyof typeof classes;level:number;stats:Stats;core:Stat[];loadout:Loadout[];armor:string;flasks:string;progression:{stage:string;text:string}[];alternatives:string[];encounters:string[]};
export type RecordNode = {id:string;name:string;kind:Kind;category:string;summary:string;dlc:boolean;art:string;tags:string[];facts?:[string,string][];requirements?:Partial<Stats>;sections:Section[];related:string[];sources:Source[];build?:Build};
