export const stats:Stat[]=['VIG','MND','END','STR','DEX','INT','FTH','ARC'];
export const statNames:Record<Stat,string>={VIG:'Vigor',MND:'Mind',END:'Endurance',STR:'Strength',DEX:'Dexterity',INT:'Intelligence',FTH:'Faith',ARC:'Arcane'};
